using GraphApi.Models.ARC.Archivos;namespace GraphApi.Services.ARC.Archivos{    /// <summary>    /// Define las operaciones de negocio y persistencia para Archivos.    /// </summary>    public interface IArchivosService    {        /// <summary>        /// Obtiene la lista de Archivos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadArchivos>> GetArchivos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Archivos con filtros opcionales.        /// </summary>        /// <param name="archivoID">Filtro opcional para ArchivoID.</param>        /// <param name="nombre">Filtro opcional para Nombre.</param>        /// <param name="ruta">Filtro opcional para Ruta.</param>        /// <param name="tipoArchivoID">Filtro opcional para TipoArchivoID.</param>        /// <param name="tipoArchivo">Filtro opcional para TipoArchivo.</param>        /// <param name="esPrivado">Filtro opcional para EsPrivado.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetArchivosDynamic(            int? archivoID,            string? nombre,            string? ruta,            int? tipoArchivoID,            string? tipoArchivo,            bool? esPrivado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Archivo.        /// </summary>        /// <param name="objInput">Datos para crear el Archivo.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadArchivos> CreateArchivos(            clCreateArchivos objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Archivo.        /// </summary>        /// <param name="objInput">Datos para actualizar el Archivo, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadArchivos?> UpdateArchivos(            clUpdateArchivos objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Archivo por su ID.        /// </summary>        /// <param name="nArchivosID">ID del Archivo a eliminar.</param>        Task<bool> DeleteArchivos(int nArchivosID);    }}